    /** 按厂商或产品的名字找标志（名字里带关键词就认，不分大小写）；认不出来返回 null。 */
    fun find(name: String): BrandLogo? {
        val n = name.lowercase()
        if (n.contains("claude") || n.contains("anthropic")) return Claude
        if (n.contains("gemini") || n.contains("google") || n.contains("谷歌")) return Gemini
        if (n.contains("deepseek") || n.contains("深度求索")) return DeepSeek
        if (n.contains("qwen") || n.contains("通义") || n.contains("千问") || n.contains("阿里")) return Qwen
        if (n.contains("kimi") || n.contains("月之暗面") || n.contains("moonshot")) return Kimi
        if (n.contains("minimax")) return MiniMax
        if (n.contains("豆包") || n.contains("doubao") || n.contains("字节")) return Doubao
        if (n.contains("智谱") || n.contains("zhipu") || n.contains("glm")) return Zhipu
        return null
    }

    /** 工具自己的像素图标（Claude Code、OpenCode）；其余工具返回 null。 */
    fun tool(name: String): BrandLogo? {
        val n = name.lowercase()
        if (n.contains("opencode")) return ToolOpenCode
        if (n.contains("claude")) return ToolClaudeCode
        return null
    }
}

private fun fillIcon(name: String, path: String): ImageVector =
    ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f)
        .addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black))
        .build()
